onClick:
{{
  (async () => {
    // 1. Eingaben & aktives Ventil sichern
    const modusWert = 'Jetzt';
    const jetzigerZeitstempel = moment().format('DD.MM.YYYY HH:mm');

    const rawActive = String(appsmith.store.activeVentil || "").trim();
    const activeV = !isNaN(parseFloat(rawActive)) 
      ? parseFloat(rawActive).toFixed(2) 
      : rawActive;

    const bemerkungText = inp_Bemerkung.text || "";

    // 2. UI sofort schließen & Formular zurücksetzen
    closeModal('Modal_Programm');
    resetWidget('inp_Bemerkung', true);

    // 3. Aktuellen Store laden
    let daten = [...(appsmith.store.lokaleBewaesserungData || Bewaesserung_Lesen.data || [])];

    // 4. Unfertigen Eintrag suchen
    let existIndex = -1;
    for (let i = 0; i < daten.length; i++) {
      const vRow = String(daten[i].Ventil || "").trim();
      const match = (vRow === activeV) || 
                    (!isNaN(parseFloat(vRow)) && parseFloat(vRow) === parseFloat(activeV));
      const unfertig = String(daten[i].Status || "").trim().toLowerCase() !== "fertig";

      if (match && unfertig) {
        existIndex = i;
        break;
      }
    }

    // 5. Neuer Eintrag für die lokale Anzeige
    const neuerEintrag = {
      Ventil: activeV,
      Modus: modusWert,
      Programm: appsmith.store.selectedProg || "",
      Zeitstempel: jetzigerZeitstempel,
      Bemerkung: bemerkungText,
      Status: 'Offen'
    };

    if (existIndex !== -1) {
      daten[existIndex] = { ...daten[existIndex], ...neuerEintrag };
    } else {
      daten.unshift(neuerEintrag);
    }

    // 6. STORE UPDATEN & RE-RENDER TRIGGERN
    await storeValue('selectedModus', modusWert);
    await storeValue('lokaleBewaesserungData', [...daten]);
    await storeValue('lastUpdate', Date.now());

    // 7. Im Hintergrund in Google Sheets speichern (OHNE Refetch/Reload!)
    try {
      if (existIndex !== -1) {
        await Bewaesserung_Update_Eintrag.run({
          "realRowIndex": existIndex,
          "programm": appsmith.store.selectedProg,
          "modus": modusWert,
          "zeitstempel": jetzigerZeitstempel,
          "bemerkung": bemerkungText
        });
      } else {
        await Bewaesserung_Speichern.run({
          "ventilName": activeV,
          "programm": appsmith.store.selectedProg,
          "modus": modusWert,
          "zeitstempel": jetzigerZeitstempel,
          "bemerkung": bemerkungText,
          "stammdaten": Stammdaten.data 
        });
      }

      await Stammdaten_Update.run({ "neuerStatus": "" });

    } catch (e) {
      showAlert("Fehler beim Speichern: " + e.message, "error");
    }
  })()
}}
